const updateExpenseField = `-- name: UpdateExpenseField :one
UPDATE expenses SET
    expense_date      = CASE WHEN $1::text = 'date' THEN $2::date ELSE expense_date END,
    period            = CASE WHEN $1::text = 'date' THEN to_char($2::date, 'YYYY-MM') ELSE period END,
    amount            = CASE WHEN $1::text = 'total_amount' THEN $3::numeric ELSE amount END,
    tax_amount        = CASE WHEN $1::text = 'tax_amount' THEN $3::numeric ELSE tax_amount END,
    tax_rate          = CASE WHEN $1::text = 'tax_rate' THEN $3::numeric ELSE tax_rate END,
    vendor_tax_number = CASE WHEN $1::text = 'vendor_tax_number' THEN $4::text ELSE vendor_tax_number END,
    vendor_name       = CASE WHEN $1::text = 'vendor_name' THEN $4::text ELSE vendor_name END,
    receipt_number    = CASE WHEN $1::text = 'receipt_number' THEN $4::text ELSE receipt_number END,
    vehicle_plate     = CASE WHEN $1::text = 'vehicle_plate' THEN $4::text ELSE vehicle_plate END,
    z_report_number   = CASE WHEN $1::text = 'z_report_number' THEN $4::text ELSE z_report_number END,
    okc_serial_number = CASE WHEN $1::text = 'okc_serial_number' THEN $4::text ELSE okc_serial_number END,
    payment_method    = CASE WHEN $1::text = 'payment_method' THEN $4::text ELSE payment_method END,
    tax_exclusive_amount = CASE
        WHEN $1::text IN ('total_amount', 'tax_amount') THEN
            (CASE WHEN $1::text = 'total_amount' THEN $3::numeric ELSE amount END)
          - COALESCE(CASE WHEN $1::text = 'tax_amount' THEN $3::numeric ELSE tax_amount END, 0)
        ELSE tax_exclusive_amount END,
    ocr_fields = jsonb_set(ocr_fields, ARRAY[$1::text, 'reviewed'], 'true'::jsonb, true)
WHERE taxpayer_id = $5 AND id = $6 AND approval_status = 'pending'
RETURNING id, uuid, taxpayer_id, source_system, source_id, capture_method, expense_date, period, amount, currency, tax_rate, tax_exclusive_amount, tax_amount, description, receipt_type, vendor_tax_number, vendor_name, receipt_number, z_report_number, okc_serial_number, vehicle_plate, payment_method, is_deductible, approval_status, ocr_confidence, ocr_fields, attachment_id, raw_payload, content_hash, approved_by, approved_at, created_at, updated_at
`

